import Foundation
import Testing
import TranscriberCore
@testable import SubtitlePostProcessing

/// Cases generated by Tools/parity/make_postprocessing_fixture.py, which runs the
/// original enforce_segment_timeline / merge_segments on the same input.
struct SubtitlePostProcessorTests {
    @Test(arguments: try PostProcessingFixture.load().cases)
    func matchesOriginalPostProcessing(_ testCase: PostProcessingFixture.Case) {
        let result = SubtitlePostProcessor.process(testCase.segments.map(\.timedText), settings: ChickenRiceDefaults.merge)
        #expect(result == testCase.expected.map(\.timedText), "\(testCase.name)")
    }

    @Test func keepsLongerTextWhenNextSegmentRepeatsThePrevious() {
        let segments = [
            TimedText(start: AudioTime(milliseconds: 0), end: AudioTime(milliseconds: 1_000), text: "こんにちは"),
            TimedText(start: AudioTime(milliseconds: 1_500), end: AudioTime(milliseconds: 3_000), text: "こんにちは、元気？"),
        ]
        let merged = SegmentMerger.merged(segments, settings: ChickenRiceDefaults.merge)
        #expect(merged == [
            TimedText(start: AudioTime(milliseconds: 0), end: AudioTime(milliseconds: 3_000), text: "こんにちは、元気？"),
        ])
    }
}

struct PostProcessingFixture: Decodable {
    struct Case: Decodable, Sendable, CustomTestStringConvertible {
        let name: String
        let segments: [Segment]
        let expected: [Segment]

        var testDescription: String { name }
    }

    struct Segment: Decodable, Sendable {
        let start: Int
        let end: Int
        let text: String

        var timedText: TimedText {
            TimedText(start: AudioTime(milliseconds: start), end: AudioTime(milliseconds: end), text: text)
        }
    }

    let cases: [Case]

    static func load() throws -> PostProcessingFixture {
        let url = try #require(Bundle.module.url(forResource: "postprocessing-cases", withExtension: "json", subdirectory: "Fixtures"))
        return try JSONDecoder().decode(PostProcessingFixture.self, from: Data(contentsOf: url))
    }
}
